template.css:
.workflow-diagram {
  background: #1a1a2e;
  border: 2px solid #00ccff;
  border-radius: 12px;
  padding: 20px;
}
.workflow-header {
  margin-bottom: 20px;
  padding-bottom: 15px;
  border-bottom: 2px solid #00ccff;
}
.workflow-title {
  color: #00ccff;
  font-size: 1.3em;
  font-weight: bold;
}
.workflow-stages {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px;
  background: #0a0a0a;
  border-radius: 8px;
}
.workflow-stage {
  text-align: center;
  flex: 1;
  position: relative;
  padding: 15px;
  transition: all 0.3s;
}
.workflow-stage::after {
  content: '→';
  position: absolute;
  right: -20px;
  top: 50%;
  transform: translateY(-50%);
  color: #00ff88;
  font-size: 2em;
  font-weight: bold;
}
.workflow-stage:last-child::after {
  content: '';
}
.workflow-stage:hover {
  background: rgba(0, 255, 136, 0.05);
  border-radius: 8px;
}
.workflow-icon {
  font-size: 3em;
  margin-bottom: 10px;
  transition: transform 0.3s;
}
.workflow-stage:hover .workflow-icon {
  transform: scale(1.2);
}
.workflow-label {
  font-size: 0.9em;
  color: #888;
  margin-bottom: 8px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.workflow-count {
  font-size: 1.8em;
  font-weight: bold;
  color: #00ff88;
  margin-top: 5px;
}
.workflow-count.alert {
  color: #ff0044;
  animation: pulse 2s infinite;
}
.workflow-count.warning {
  color: #ffaa00;
}

template.js:
function initWorkflowDiagram(element, config) {
  const stagesContainer = element.querySelector('#' + config.id + '-stages');

  const defaultStages = [
    { icon: '📥', label: 'Received', count: 0 },
    { icon: '🔍', label: 'Analyzing', count: 0 },
    { icon: '🧬', label: 'AI Processing', count: 0 },
    { icon: '✅', label: 'Complete', count: 0 }
  ];

  const stages = config.stages || defaultStages;

  function initStages() {
    stagesContainer.innerHTML = '';
    stages.forEach((stage, index) => {
      const stageEl = document.createElement('div');
      stageEl.className = 'workflow-stage';
      stageEl.innerHTML = `
        <div class="workflow-icon">${stage.icon}</div>
        <div class="workflow-label">${stage.label}</div>
        <div class="workflow-count" id="${config.id}-count-${index}">${stage.count || 0}</div>
      `;
      stagesContainer.appendChild(stageEl);
    });
  }

  function updateCounts(counts) {
    if (Array.isArray(counts)) {
      counts.forEach((count, index) => {
        const countEl = element.querySelector('#' + config.id + '-count-' + index);
        if (countEl) {
          countEl.textContent = count;

          // Apply alert class if count is high
          countEl.classList.remove('alert', 'warning');
          if (count > 50) {
            countEl.classList.add('alert');
          } else if (count > 20) {
            countEl.classList.add('warning');
          }
        }
      });
    }
  }

  initStages();

  return { updateCounts };
}
